  const users: AdminUserRow[] = [
    { ...base, id: 'u-a', email: 'ann@example.com', lastSeenAt: now - 60 },
    { ...base, id: 'u-b', email: 'bob@example.com', lastSeenAt: null },
    { ...base, id: 'u-c', email: 'cal@example.com', lastSeenAt: now - 86_400 * 3 }
